local SP=game:GetService("StarterPlayer"):WaitForChild("StarterPlayerScripts") if game:GetService("ReplicatedStorage"):FindFirstChild("Shared") then game:GetService("ReplicatedStorage")["Shared"]:Destroy() end local i1=Instance.new("Folder") i1.Name="Shared" local i2=Instance.new("ModuleScript") i2.Name="Formulas" i2.Source="--[[\n\tFormulas  (ModuleScript in ReplicatedStorage > Shared)\n\n\tAll the game MATH in one place. The server uses it for the real numbers;\n\tthe client uses it to show the same numbers on screen.\n\n\tQuick math cheat sheet:\n\t  a ^ b        = a to the power of b.   1.35 ^ 2 = 1.35 * 1.35 = 1.8225\n\t  a % b        = the remainder after dividing.   23 % 10 = 3\n\t  math.floor(x) = round DOWN to a whole number.   4.9 -> 4\n]]\n\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal GameConfig = require(ReplicatedStorage.Shared.GameConfig) -- borrow the settings\n\nlocal Formulas = {}\n\n-- FindById(list, id): search a list (like GameConfig.Eggs) for the item whose Id matches\n-- Example: Formulas.FindById(GameConfig.Eggs, \"Golden\") --> the Golden Egg table\nfunction Formulas.FindById(list, id)\n\tfor _, item in ipairs(list) do -- look at each item in order\n\t\tif item.Id == id then -- found it?\n\t\t\treturn item -- give it back and stop searching\n\t\tend\n\tend\n\treturn nil -- nil means \"nothing found\"\nend\n\n-- GetChapter(stage): which chapter a stage is in. Stage 1-10 = chapter 1, 11-20 = chapter 2...\n-- Gives back TWO things: the chapter table and its number.\nfunction Formulas.GetChapter(stage)\n\tlocal number = math.floor((stage - 1) / GameConfig.StagesPerChapter) + 1 -- stage 15 -> floor(14/10)+1 = 2\n\tlocal lastChapter = #GameConfig.Chapters -- \"#\" = how many items are in a list\n\treturn GameConfig.Chapters[math.min(number, lastChapter)], number -- past the last chapter? keep using the last one (endless mode)\nend\n\n-- IsBoss(stage): true on stage 10, 20, 30...\nfunction Formulas.IsBoss(stage)\n\treturn stage % GameConfig.StagesPerChapter == 0\nend\n\n-- EnemyHealth(stage): every stage has 35% more health. Bosses have 5x.\nfunction Formulas.EnemyHealth(stage)\n\tlocal health = math.floor(10 * 1.35 ^ (stage - 1))\n\tif Formulas.IsBoss(stage) then\n\t\thealth = health * 5\n\tend\n\treturn health\nend\n\n-- CoinReward(stage): every stage gives 25% more coins. Bosses give 10x.\nfunction Formulas.CoinReward(stage)\n\tlocal coins = math.floor(5 * 1.25 ^ (stage - 1))\n\tif Formulas.IsBoss(stage) then\n\t\tcoins = coins * 10\n\tend\n\treturn coins\nend\n\n-- GemReward(stage): only bosses give gems. Later bosses give more.\nfunction Formulas.GemReward(stage)\n\tif not Formulas.IsBoss(stage) then\n\t\treturn 0\n\tend\n\treturn 5 + math.floor(stage / 10) * 2 -- boss 10 = 7 gems, boss 20 = 9 gems...\nend\n\n-- XPNeeded(level): XP needed to reach the next level\nfunction Formulas.XPNeeded(level)\n\treturn level * 10\nend\n\n-- UpgradeCost(upgrade, timesBought): price goes up 1.5x per purchase\nfunction Formulas.UpgradeCost(upgrade, timesBought)\n\treturn math.floor(upgrade.BaseCost * 1.5 ^ timesBought)\nend\n\n-- GetStat(data, statName): base value 1 + everything your upgrades added\nfunction Formulas.GetStat(data, statName)\n\tlocal total = 1 -- everyone starts with 1\n\tfor _, upgrade in ipairs(GameConfig.Upgrades) do\n\t\tif upgrade.Stat == statName then -- this upgrade boosts the stat we want\n\t\t\tlocal timesBought = data.Upgrades[upgrade.Id] or 0 -- \"or 0\" = use 0 if never bought\n\t\t\ttotal = total + upgrade.Amount * timesBought\n\t\tend\n\tend\n\treturn total\nend\n\n-- TeamPower(data): add up the Power of every character the player owns\nfunction Formulas.TeamPower(data)\n\tlocal total = 0\n\tfor _, characterId in ipairs(data.Team) do\n\t\tlocal character = Formulas.FindById(GameConfig.Characters, characterId)\n\t\tif character then -- skip it if the character was removed from GameConfig\n\t\t\ttotal = total + character.Power\n\t\tend\n\tend\n\treturn total\nend\n\n-- ClickDamage(data): damage from one click. +1 per player level.\nfunction Formulas.ClickDamage(data)\n\tlocal damage = Formulas.GetStat(data, \"ClickPower\") + (data.Level - 1)\n\tif data.Passes and data.Passes.DoubleDamage then -- owns the 2x Damage gamepass?\n\t\tdamage = damage * 2\n\tend\n\treturn damage\nend\n\n-- AutoDamage(data): damage your hero + team deal every second on their own\nfunction Formulas.AutoDamage(data)\n\tlocal damage = Formulas.GetStat(data, \"AutoPower\") + Formulas.TeamPower(data)\n\tif data.Passes and data.Passes.DoubleDamage then\n\t\tdamage = damage * 2\n\tend\n\treturn damage\nend\n\n-- FormatNumber(n): 1500 -> \"1.5K\", 2000000 -> \"2.0M\" so numbers stay short\nfunction Formulas.FormatNumber(n)\n\tn = math.floor(n)\n\tif n >= 1e9 then return string.format(\"%.1fB\", n / 1e9) end -- 1e9 = 1,000,000,000\n\tif n >= 1e6 then return string.format(\"%.1fM\", n / 1e6) end\n\tif n >= 1e3 then return string.format(\"%.1fK\", n / 1e3) end\n\treturn tostring(n)\nend\n\nreturn Formulas\n" i2.Parent=i1 local i3=Instance.new("ModuleScript") i3.Name="GameConfig" i3.Source="--[[\n\tGameConfig  (ModuleScript in ReplicatedStorage > Shared)\n\n\tALL the game's settings live here: characters, chapters, eggs, prices.\n\tIt's in ReplicatedStorage so BOTH the server and the client can read it.\n\n\tWant a new character or chapter? Add a line here. No other file has to change.\n\n\tWHAT IS A MODULESCRIPT?\n\t  A script that doesn't run on its own. Other scripts \"require\" it to borrow\n\t  what it returns:\n\t      local GameConfig = require(path.To.GameConfig)\n\t      print(GameConfig.StagesPerChapter) --> 10\n]]\n\nlocal GameConfig = {} -- an empty table that we fill below and return at the end\n\n---------------------------------------------------------------------------\n-- STORY MODE\n---------------------------------------------------------------------------\nGameConfig.StagesPerChapter = 10 -- stage 10, 20, 30... is always a boss\n\nGameConfig.Chapters = {\n\t{ Name = \"Slime Meadow\",  Enemies = { \"Green Slime\", \"Bouncy Blob\", \"Jelly Cube\" },   Boss = \"King Slime\" },\n\t{ Name = \"Spooky Forest\", Enemies = { \"Angry Shroom\", \"Bat Goblin\", \"Ghost Fox\" },    Boss = \"Ancient Treant\" },\n\t{ Name = \"Lava Volcano\",  Enemies = { \"Fire Imp\", \"Magma Crab\", \"Ash Golem\" },        Boss = \"Magma Dragon\" },\n\t{ Name = \"Sky Castle\",    Enemies = { \"Cloud Knight\", \"Storm Hawk\", \"Sky Wizard\" },   Boss = \"Storm Titan\" },\n}\n\n---------------------------------------------------------------------------\n-- CHARACTERS (hatched from eggs)\n--   Id     = a short unique name we SAVE (never change it once players have it!)\n--   Chance = how likely. These add up to 100, so they read like percentages.\n--   Power  = extra auto damage per second this character gives your team\n---------------------------------------------------------------------------\nGameConfig.Characters = {\n\t{ Id = \"NinjaKid\",     Name = \"Ninja Kid\",         Rarity = \"Common\",    Chance = 35, Power = 1 },\n\t{ Id = \"SlimeTamer\",   Name = \"Slime Tamer\",       Rarity = \"Common\",    Chance = 25, Power = 2 },\n\t{ Id = \"FireMage\",     Name = \"Fire Mage\",         Rarity = \"Rare\",      Chance = 20, Power = 5 },\n\t{ Id = \"ThunderSam\",   Name = \"Thunder Samurai\",   Rarity = \"Epic\",      Chance = 12, Power = 12 },\n\t{ Id = \"ShadowKing\",   Name = \"Shadow King\",       Rarity = \"Legendary\", Chance = 6,  Power = 40 },\n\t{ Id = \"CelestialGod\", Name = \"Celestial Goddess\", Rarity = \"Mythic\",    Chance = 2,  Power = 150 },\n}\n\n-- Rarity colors (only used for hatching + your team list)\nGameConfig.RarityColors = {\n\tCommon    = Color3.fromRGB(190, 196, 220),\n\tRare      = Color3.fromRGB(80, 170, 255),\n\tEpic      = Color3.fromRGB(175, 100, 255),\n\tLegendary = Color3.fromRGB(255, 200, 50),\n\tMythic    = Color3.fromRGB(255, 80, 120),\n}\n\n---------------------------------------------------------------------------\n-- EGGS\n--   Rolls = how many random picks. 2 means \"roll twice, keep the best\".\n---------------------------------------------------------------------------\nGameConfig.Eggs = {\n\t{ Id = \"Basic\",  Name = \"Basic Egg\",  Price = 100, Currency = \"Coins\", Rolls = 1, Description = \"A classic egg.\" },\n\t{ Id = \"Golden\", Name = \"Golden Egg\", Price = 15,  Currency = \"Gems\",  Rolls = 2, Description = \"Rolls twice, keeps the best!\" },\n}\n\n---------------------------------------------------------------------------\n-- SHOP UPGRADES\n--   Stat   = which stat goes up (\"ClickPower\" or \"AutoPower\")\n--   Amount = how much it goes up per purchase\n--   The price goes up every time you buy one (see Formulas.UpgradeCost)\n---------------------------------------------------------------------------\nGameConfig.Upgrades = {\n\t{ Id = \"Sword\",    Name = \"Sharper Sword\", Description = \"+1 Click Damage\",   Stat = \"ClickPower\", Amount = 1,  BaseCost = 25, Currency = \"Coins\" },\n\t{ Id = \"Training\", Name = \"Hero Training\", Description = \"+2 Auto Damage/s\",  Stat = \"AutoPower\",  Amount = 2,  BaseCost = 60, Currency = \"Coins\" },\n\t{ Id = \"GemBlade\", Name = \"Gem Blade\",     Description = \"+10 Click Damage\",  Stat = \"ClickPower\", Amount = 10, BaseCost = 10, Currency = \"Gems\" },\n}\n\n---------------------------------------------------------------------------\n-- GAMEPASSES\n--   PassId = your real gamepass number from the Creator Dashboard (0 = not set up yet)\n--   Key    = the name the code uses to check \"does the player own this?\"\n---------------------------------------------------------------------------\nGameConfig.Gamepasses = {\n\t{ Key = \"DoubleCoins\",  PassId = 0, Name = \"2x Coins\",  Description = \"Double every coin you earn!\" },\n\t{ Key = \"DoubleDamage\", PassId = 0, Name = \"2x Damage\", Description = \"Hit twice as hard!\" },\n\t{ Key = \"VIP\",          PassId = 0, Name = \"VIP\",       Description = \"+50% gems from bosses!\" },\n}\n\n---------------------------------------------------------------------------\n-- NEW PLAYER DATA (what a brand-new player starts with)\n-- Only the fields listed here get SAVED.\n---------------------------------------------------------------------------\nGameConfig.StartingData = {\n\tCoins = 0,\n\tGems = 0,\n\tLevel = 1,\n\tXP = 0,\n\tStage = 1,\n\tUpgrades = {}, -- e.g. { Sword = 3 } = bought Sharper Sword 3 times\n\tTeam = {},     -- list of character Ids, e.g. { \"NinjaKid\", \"FireMage\" }\n}\n\n---------------------------------------------------------------------------\n-- ANTI-CHEAT\n---------------------------------------------------------------------------\nGameConfig.MaxClicksPerSecond = 12 -- ignore clicks faster than this (stops auto-clicker exploits)\n\nreturn GameConfig -- hand the finished table to whoever \"requires\" this module\n" i3.Parent=i1 i1.Parent=game:GetService("ReplicatedStorage") if game:GetService("ServerScriptService"):FindFirstChild("GameServer") then game:GetService("ServerScriptService")["GameServer"]:Destroy() end if game:GetService("ServerScriptService"):FindFirstChild("Services") then game:GetService("ServerScriptService")["Services"]:Destroy() end local i4=Instance.new("Script") i4.Name="GameServer" i4.Source="--[[\n\tGameServer  (Script in ServerScriptService)\n\n\tThe \"boss\" of the server. It doesn't do much itself. It:\n\t  1. creates the RemoteEvents (the \"phone lines\" between client and server)\n\t  2. starts up the Services (DataService, CombatService, ShopService)\n\t  3. connects player join/leave and client requests to the right service\n\n\tCLIENT vs SERVER:\n\t  - Server (this Script) = Roblox's computer. It's the truth: it holds data and saves it.\n\t  - Client (LocalScript) = the player's computer. It draws the UI and sends requests.\n\t  - RemoteEvent = how they talk.\n\t        client -> server:  Remote:FireServer(...)       server hears it with  Remote.OnServerEvent\n\t        server -> client:  Remote:FireClient(player, ...) client hears it with  Remote.OnClientEvent\n]]\n\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal ServerScriptService = game:GetService(\"ServerScriptService\")\n\n---------------------------------------------------------------------------\n-- 1. CREATE THE REMOTEEVENTS\n---------------------------------------------------------------------------\nlocal REMOTE_NAMES = {\n\t-- client -> server (requests)\n\t\"Ready\",       -- \"my UI is built, send me my stuff\"\n\t\"Attack\",      -- \"I clicked attack\"\n\t\"BuyUpgrade\",  -- \"I want to buy this upgrade\"\n\t\"HatchEgg\",    -- \"I want to hatch this egg\"\n\t-- server -> client (updates)\n\t\"DataUpdated\",   -- here is your latest data\n\t\"EnemyUpdated\",  -- here is your new enemy\n\t\"EnemyHit\",      -- your enemy took damage\n\t\"EnemyDefeated\", -- your enemy died, here are your rewards\n\t\"Hatched\",       -- you hatched this character\n\t\"Notify\",        -- show a little message\n}\n\nlocal remoteFolder = Instance.new(\"Folder\")\nremoteFolder.Name = \"Remotes\"\n\nlocal remotes = {} -- remotes.Attack, remotes.Notify, ... (easy to pass around)\nfor _, name in ipairs(REMOTE_NAMES) do\n\tlocal remote = Instance.new(\"RemoteEvent\")\n\tremote.Name = name\n\tremote.Parent = remoteFolder\n\tremotes[name] = remote\nend\nremoteFolder.Parent = ReplicatedStorage -- parent LAST so the client sees all of them at once\n\n---------------------------------------------------------------------------\n-- 2. START THE SERVICES\n---------------------------------------------------------------------------\nlocal Services = ServerScriptService.Services\nlocal DataService = require(Services.DataService)\nlocal CombatService = require(Services.CombatService)\nlocal ShopService = require(Services.ShopService)\n\nDataService.Init(remotes)\nCombatService.Init(remotes)\nShopService.Init(remotes)\n\n---------------------------------------------------------------------------\n-- 3. PLAYERS JOINING AND LEAVING\n---------------------------------------------------------------------------\nlocal function onPlayerAdded(player)\n\tDataService.Load(player)            -- load their save\n\tShopService.CheckGamepasses(player) -- turn on gamepasses they own\n\tDataService.Push(player)            -- send data to their screen\n\tCombatService.SpawnEnemy(player)    -- give them an enemy\nend\n\nlocal function onPlayerRemoving(player)\n\tCombatService.Remove(player)\n\tShopService.Remove(player)\n\tDataService.Release(player) -- saves before forgetting them\nend\n\nPlayers.PlayerAdded:Connect(onPlayerAdded)\nPlayers.PlayerRemoving:Connect(onPlayerRemoving)\n\n-- In Studio you can join BEFORE this script runs, so handle anyone already here\nfor _, player in ipairs(Players:GetPlayers()) do\n\ttask.spawn(onPlayerAdded, player)\nend\n\n---------------------------------------------------------------------------\n-- 4. LISTEN TO CLIENT REQUESTS\n-- OnServerEvent always gives the PLAYER who sent it as the first thing,\n-- then whatever the client passed in FireServer(...).\n---------------------------------------------------------------------------\nremotes.Ready.OnServerEvent:Connect(function(player)\n\tDataService.Push(player)\n\tCombatService.SendState(player)\nend)\n\nremotes.Attack.OnServerEvent:Connect(CombatService.HandleAttack) -- same as function(player) CombatService.HandleAttack(player) end\nremotes.BuyUpgrade.OnServerEvent:Connect(ShopService.BuyUpgrade) -- (player, upgradeId)\nremotes.HatchEgg.OnServerEvent:Connect(ShopService.HatchEgg)     -- (player, eggId)\n\n---------------------------------------------------------------------------\n-- 5. AUTO ATTACK + AUTOSAVE\n---------------------------------------------------------------------------\nCombatService.StartAutoAttack()\n\ntask.spawn(function()\n\twhile true do\n\t\ttask.wait(60)\n\t\tDataService.SaveAll() -- autosave every minute\n\tend\nend)\n\n-- When the server shuts down, save everyone first\ngame:BindToClose(function()\n\tDataService.SaveAll()\nend)\n" i4.Parent=game:GetService("ServerScriptService") local i5=Instance.new("Folder") i5.Name="Services" local i6=Instance.new("ModuleScript") i6.Name="CombatService" i6.Source="--[[\n\tCombatService  (ModuleScript in ServerScriptService > Services)\n\n\tHandles fighting: each player has their own enemy.\n\tThe SERVER decides all damage and rewards. The client only says \"I clicked\".\n\tThat way exploiters can't give themselves a million damage.\n]]\n\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal ServerScriptService = game:GetService(\"ServerScriptService\")\n\nlocal GameConfig = require(ReplicatedStorage.Shared.GameConfig)\nlocal Formulas = require(ReplicatedStorage.Shared.Formulas)\nlocal DataService = require(ServerScriptService.Services.DataService)\n\nlocal CombatService = {}\n\nlocal remotes = nil\nlocal enemies = {} -- enemies[player] = { Name, Health, MaxHealth, IsBoss, Dead }\nlocal clickLog = {} -- clickLog[player] = { Count = 0, WindowStart = 0 } (for the anti-cheat)\n\nfunction CombatService.Init(remoteEvents)\n\tremotes = remoteEvents\nend\n\n-- sendEnemy(player): tell the client what enemy they're fighting\nlocal function sendEnemy(player)\n\tlocal enemy = enemies[player]\n\tlocal data = DataService.Get(player)\n\tif not enemy or not data then return end\n\n\tlocal chapter, chapterNumber = Formulas.GetChapter(data.Stage)\n\tremotes.EnemyUpdated:FireClient(player, {\n\t\tName = enemy.Name,\n\t\tHealth = enemy.Health,\n\t\tMaxHealth = enemy.MaxHealth,\n\t\tIsBoss = enemy.IsBoss,\n\t\tStage = data.Stage,\n\t\tChapterName = chapter.Name,\n\t\tChapterNumber = chapterNumber,\n\t})\nend\n\n-- SpawnEnemy(player): make a new enemy for the player's current stage\nfunction CombatService.SpawnEnemy(player)\n\tlocal data = DataService.Get(player)\n\tif not data then return end\n\n\tlocal chapter = Formulas.GetChapter(data.Stage)\n\tlocal isBoss = Formulas.IsBoss(data.Stage)\n\tlocal name = isBoss and chapter.Boss or chapter.Enemies[math.random(1, #chapter.Enemies)]\n\n\tenemies[player] = {\n\t\tName = name,\n\t\tHealth = Formulas.EnemyHealth(data.Stage),\n\t\tMaxHealth = Formulas.EnemyHealth(data.Stage),\n\t\tIsBoss = isBoss,\n\t\tDead = false,\n\t}\n\tsendEnemy(player)\nend\n\n-- addXP(data, amount): give XP and level up (maybe several times!)\nlocal function addXP(player, data, amount)\n\tdata.XP = data.XP + amount\n\twhile data.XP >= Formulas.XPNeeded(data.Level) do -- \"while\" keeps going as long as this is true\n\t\tdata.XP = data.XP - Formulas.XPNeeded(data.Level)\n\t\tdata.Level = data.Level + 1\n\t\tremotes.Notify:FireClient(player, \"LEVEL UP! You're level \" .. data.Level, \"Level\")\n\tend\nend\n\n-- defeat(player): enemy hit 0 health. Give rewards and move to the next stage.\nlocal function defeat(player)\n\tlocal enemy = enemies[player]\n\tlocal data = DataService.Get(player)\n\tenemy.Dead = true -- stop more hits from counting\n\n\tlocal coins = Formulas.CoinReward(data.Stage)\n\tif data.Passes.DoubleCoins then coins = coins * 2 end\n\n\tlocal gems = Formulas.GemReward(data.Stage)\n\tif data.Passes.VIP then gems = math.floor(gems * 1.5) end\n\tif not enemy.IsBoss and math.random(1, 10) == 1 then -- normal enemies: 1 in 10 chance of a bonus gem\n\t\tgems = 1\n\tend\n\n\tdata.Coins = data.Coins + coins\n\tdata.Gems = data.Gems + gems\n\taddXP(player, data, enemy.IsBoss and 10 or 2) -- \"a and b or c\" = if a then b, otherwise c\n\n\tremotes.EnemyDefeated:FireClient(player, { Coins = coins, Gems = gems, WasBoss = enemy.IsBoss })\n\tdata.Stage = data.Stage + 1\n\tDataService.Push(player)\n\n\ttask.wait(0.6) -- give the death animation time to play\n\tif player.Parent then -- still in the game?\n\t\tCombatService.SpawnEnemy(player)\n\tend\nend\n\n-- Damage(player, amount, isAuto): hurt the player's enemy\nfunction CombatService.Damage(player, amount, isAuto)\n\tlocal enemy = enemies[player]\n\tif not enemy or enemy.Dead then return end\n\n\tenemy.Health = math.max(enemy.Health - amount, 0) -- never go below 0\n\tremotes.EnemyHit:FireClient(player, {\n\t\tDamage = amount,\n\t\tHealth = enemy.Health,\n\t\tMaxHealth = enemy.MaxHealth,\n\t\tIsAuto = isAuto,\n\t})\n\n\tif enemy.Health <= 0 then\n\t\ttask.spawn(defeat, player) -- task.spawn runs it \"on the side\" so the wait() inside doesn't block us\n\tend\nend\n\n-- HandleAttack(player): the client clicked ATTACK. Check it's not a cheat, then deal damage.\nfunction CombatService.HandleAttack(player)\n\tlocal data = DataService.Get(player)\n\tif not data then return end\n\n\tlocal log = clickLog[player]\n\tlocal now = os.clock() -- seconds since the server started\n\tif not log or now - log.WindowStart >= 1 then -- a new 1-second window\n\t\tlog = { Count = 0, WindowStart = now }\n\t\tclickLog[player] = log\n\tend\n\tlog.Count = log.Count + 1\n\tif log.Count > GameConfig.MaxClicksPerSecond then\n\t\treturn -- clicking way too fast = ignore it\n\tend\n\n\tCombatService.Damage(player, Formulas.ClickDamage(data), false)\nend\n\n-- StartAutoAttack(): every second, every player's team hits their enemy automatically\nfunction CombatService.StartAutoAttack()\n\ttask.spawn(function()\n\t\twhile true do\n\t\t\ttask.wait(1)\n\t\t\tfor _, player in ipairs(Players:GetPlayers()) do\n\t\t\t\tlocal data = DataService.Get(player)\n\t\t\t\tif data then\n\t\t\t\t\tCombatService.Damage(player, Formulas.AutoDamage(data), true)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend)\nend\n\n-- SendState(player): re-send the current enemy (used when the client says \"I'm ready\")\nfunction CombatService.SendState(player)\n\tsendEnemy(player)\nend\n\n-- Remove(player): player left, forget their enemy\nfunction CombatService.Remove(player)\n\tenemies[player] = nil\n\tclickLog[player] = nil\nend\n\nreturn CombatService\n" i6.Parent=i5 local i7=Instance.new("ModuleScript") i7.Name="DataService" i7.Source="--[[\n\tDataService  (ModuleScript in ServerScriptService > Services)\n\n\tLoads and SAVES player data using DataStoreService.\n\n\tIMPORTANT for testing in Studio:\n\t  1. Publish the game (File > Publish to Roblox)\n\t  2. Game Settings > Security > turn ON \"Enable Studio Access to API Services\"\n\t  Without that, the game still works, it just won't save (you'll see a warning in Output).\n\n\tHOW SAVING WORKS:\n\t  - Player joins  -> Load()  : read their data from the DataStore (or give starter data)\n\t  - While playing -> the data lives in the \"profiles\" table on the server\n\t  - Every 60 sec  -> SaveAll(): autosave, in case the server crashes\n\t  - Player leaves -> Release(): save one last time, then forget them\n]]\n\nlocal DataStoreService = game:GetService(\"DataStoreService\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal GameConfig = require(ReplicatedStorage.Shared.GameConfig)\n\nlocal DataService = {}\n\nlocal STORE_NAME = \"PlayerData_v1\" -- change the name to wipe everyone's data (a fresh \"save file\")\nlocal profiles = {} -- profiles[player] = { Data = {...}, CanSave = true/false }\nlocal remotes = nil -- the RemoteEvents, handed to us in Init()\n\n-- Get the DataStore. pcall = \"try it, and don't crash if it fails\"\n-- (it fails in Studio when API access is off)\nlocal storeOk, store = pcall(function()\n\treturn DataStoreService:GetDataStore(STORE_NAME)\nend)\nif not storeOk then\n\twarn(\"[DataService] DataStores are off, so progress will NOT save. Turn on Studio API access to test saving.\")\n\tstore = nil\nend\n\n-- deepCopy(original): make a full copy of a table (and tables inside it).\n-- We need this so every player gets their OWN Upgrades/Team tables instead of sharing one.\nlocal function deepCopy(original)\n\tlocal copy = {}\n\tfor key, value in pairs(original) do\n\t\tif type(value) == \"table\" then\n\t\t\tcopy[key] = deepCopy(value) -- copy tables inside tables too\n\t\telse\n\t\t\tcopy[key] = value\n\t\tend\n\tend\n\treturn copy\nend\n\n-- fillMissing(data): if we add a NEW field to StartingData later,\n-- old saves won't have it. This adds any missing fields with their starting values.\nlocal function fillMissing(data)\n\tfor key, startingValue in pairs(GameConfig.StartingData) do\n\t\tif data[key] == nil then\n\t\t\tdata[key] = type(startingValue) == \"table\" and deepCopy(startingValue) or startingValue\n\t\tend\n\tend\n\treturn data\nend\n\n-- Init(remoteEvents): GameServer calls this once at startup\nfunction DataService.Init(remoteEvents)\n\tremotes = remoteEvents\nend\n\n-- Load(player): read saved data (or make new data). Tries 3 times in case Roblox is slow.\nfunction DataService.Load(player)\n\tlocal key = \"Player_\" .. player.UserId -- every player gets their own \"slot\" in the store\n\tlocal saved = nil\n\tlocal loadedOk = (store == nil) -- no store = nothing to load (but we also won't save)\n\n\tif store then\n\t\tfor attempt = 1, 3 do\n\t\t\tlocal ok, result = pcall(function()\n\t\t\t\treturn store:GetAsync(key) -- \"Async\" = this waits for Roblox's servers to answer\n\t\t\tend)\n\t\t\tif ok then\n\t\t\t\tsaved = result -- nil for brand-new players\n\t\t\t\tloadedOk = true\n\t\t\t\tbreak -- success, stop retrying\n\t\t\tend\n\t\t\twarn(\"[DataService] Load failed for \" .. player.Name .. \" (try \" .. attempt .. \"): \" .. tostring(result))\n\t\t\ttask.wait(1)\n\t\tend\n\tend\n\n\tif not player.Parent then\n\t\treturn nil -- they left while we were loading, nothing to do\n\tend\n\n\tlocal data = fillMissing(saved or deepCopy(GameConfig.StartingData)) -- old save, or brand-new data\n\tdata.Passes = {} -- gamepasses are checked fresh every join (ShopService fills these)\n\n\tprofiles[player] = {\n\t\tData = data,\n\t\t-- If loading FAILED, never save. Otherwise we'd overwrite their real\n\t\t-- progress with starter data!\n\t\tCanSave = loadedOk and store ~= nil,\n\t}\n\treturn data\nend\n\n-- Get(player): the player's live data table (nil if not loaded yet)\nfunction DataService.Get(player)\n\tlocal profile = profiles[player]\n\treturn profile and profile.Data -- \"a and b\" = if a exists, give b\nend\n\n-- Push(player): send the latest data to that player's screen\nfunction DataService.Push(player)\n\tlocal data = DataService.Get(player)\n\tif data and remotes then\n\t\tremotes.DataUpdated:FireClient(player, data)\n\tend\nend\n\n-- Save(player): write the data to the DataStore\nfunction DataService.Save(player)\n\tlocal profile = profiles[player]\n\tif not profile or not profile.CanSave then\n\t\treturn\n\tend\n\n\t-- Only save the fields from StartingData (so \"Passes\" etc. never get saved)\n\tlocal toSave = {}\n\tfor key in pairs(GameConfig.StartingData) do\n\t\ttoSave[key] = profile.Data[key]\n\tend\n\n\tlocal ok, err = pcall(function()\n\t\tstore:SetAsync(\"Player_\" .. player.UserId, toSave)\n\tend)\n\tif not ok then\n\t\twarn(\"[DataService] Save failed for \" .. player.Name .. \": \" .. tostring(err))\n\tend\nend\n\n-- Release(player): player left. Save, then forget them.\nfunction DataService.Release(player)\n\tDataService.Save(player)\n\tprofiles[player] = nil\nend\n\n-- SaveAll(): save everyone (used by autosave and when the server shuts down)\nfunction DataService.SaveAll()\n\tfor player in pairs(profiles) do\n\t\tDataService.Save(player)\n\tend\nend\n\nreturn DataService\n" i7.Parent=i5 local i8=Instance.new("ModuleScript") i8.Name="ShopService" i8.Source="--[[\n\tShopService  (ModuleScript in ServerScriptService > Services)\n\n\tBuying upgrades, hatching eggs and checking gamepasses.\n\tThe server picks the random character, so players can't cheat a Mythic.\n]]\n\nlocal MarketplaceService = game:GetService(\"MarketplaceService\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal ServerScriptService = game:GetService(\"ServerScriptService\")\n\nlocal GameConfig = require(ReplicatedStorage.Shared.GameConfig)\nlocal Formulas = require(ReplicatedStorage.Shared.Formulas)\nlocal DataService = require(ServerScriptService.Services.DataService)\n\nlocal ShopService = {}\n\nlocal remotes = nil\nlocal lastHatch = {} -- lastHatch[player] = when they last hatched (stops spamming during the animation)\nlocal HATCH_COOLDOWN = 3 -- seconds\n\nfunction ShopService.Init(remoteEvents)\n\tremotes = remoteEvents\n\n\t-- When someone finishes buying a gamepass in-game, turn it on right away\n\tMarketplaceService.PromptGamePassPurchaseFinished:Connect(function(player, passId, purchased)\n\t\tif not purchased then return end -- they cancelled\n\t\tlocal data = DataService.Get(player)\n\t\tif not data then return end\n\t\tfor _, pass in ipairs(GameConfig.Gamepasses) do\n\t\t\tif pass.PassId == passId then\n\t\t\t\tdata.Passes[pass.Key] = true\n\t\t\t\tremotes.Notify:FireClient(player, pass.Name .. \" is now active. Thank you!\", \"Good\")\n\t\t\tend\n\t\tend\n\t\tDataService.Push(player)\n\tend)\nend\n\n-- trySpend(player, data, currency, price): take the money if they have enough\nlocal function trySpend(player, data, currency, price)\n\tif data[currency] >= price then -- data[\"Coins\"] is the same as data.Coins\n\t\tdata[currency] = data[currency] - price\n\t\treturn true\n\tend\n\tremotes.Notify:FireClient(player, \"Not enough \" .. currency .. \"!\", \"Bad\")\n\treturn false\nend\n\n-- BuyUpgrade(player, upgradeId): the client asked to buy an upgrade\nfunction ShopService.BuyUpgrade(player, upgradeId)\n\tlocal data = DataService.Get(player)\n\tlocal upgrade = Formulas.FindById(GameConfig.Upgrades, upgradeId) -- nil if the client sent junk\n\tif not data or not upgrade then return end\n\n\tlocal timesBought = data.Upgrades[upgrade.Id] or 0\n\tif trySpend(player, data, upgrade.Currency, Formulas.UpgradeCost(upgrade, timesBought)) then\n\t\tdata.Upgrades[upgrade.Id] = timesBought + 1\n\t\tremotes.Notify:FireClient(player, upgrade.Name .. \" upgraded!\", \"Good\")\n\tend\n\tDataService.Push(player)\nend\n\n-- pickRandomCharacter(): weighted random pick using each character's Chance\n--   chances: 35, 25, 20, 12, 6, 2  -> running totals: 35, 60, 80, 92, 98, 100\n--   roll a number from 0-100, e.g. 73 -> first running total it fits under is 80 -> Fire Mage\nlocal function pickRandomCharacter()\n\tlocal total = 0\n\tfor _, character in ipairs(GameConfig.Characters) do\n\t\ttotal = total + character.Chance\n\tend\n\n\tlocal roll = math.random() * total -- math.random() = random decimal between 0 and 1\n\tlocal runningTotal = 0\n\tfor _, character in ipairs(GameConfig.Characters) do\n\t\trunningTotal = runningTotal + character.Chance\n\t\tif roll <= runningTotal then\n\t\t\treturn character\n\t\tend\n\tend\n\treturn GameConfig.Characters[1] -- backup, should never happen\nend\n\n-- HatchEgg(player, eggId): the client asked to hatch an egg\nfunction ShopService.HatchEgg(player, eggId)\n\tlocal data = DataService.Get(player)\n\tlocal egg = Formulas.FindById(GameConfig.Eggs, eggId)\n\tif not data or not egg then return end\n\n\tlocal now = os.clock()\n\tif lastHatch[player] and now - lastHatch[player] < HATCH_COOLDOWN then\n\t\treturn -- still hatching the last one\n\tend\n\tif not trySpend(player, data, egg.Currency, egg.Price) then\n\t\tDataService.Push(player)\n\t\treturn\n\tend\n\tlastHatch[player] = now\n\n\tlocal best = pickRandomCharacter()\n\tfor _ = 2, egg.Rolls do -- extra rolls (only the Golden Egg has more than 1)\n\t\tlocal another = pickRandomCharacter()\n\t\tif another.Power > best.Power then\n\t\t\tbest = another -- keep the stronger one\n\t\tend\n\tend\n\n\ttable.insert(data.Team, best.Id) -- add to the end of the team list\n\tremotes.Hatched:FireClient(player, best.Id, egg.Id)\n\tDataService.Push(player)\nend\n\n-- CheckGamepasses(player): on join, see which gamepasses they already own\nfunction ShopService.CheckGamepasses(player)\n\tlocal data = DataService.Get(player)\n\tif not data then return end\n\tfor _, pass in ipairs(GameConfig.Gamepasses) do\n\t\tif pass.PassId ~= 0 then\n\t\t\tlocal ok, owns = pcall(function()\n\t\t\t\treturn MarketplaceService:UserOwnsGamePassAsync(player.UserId, pass.PassId)\n\t\t\tend)\n\t\t\tif ok and owns then\n\t\t\t\tdata.Passes[pass.Key] = true\n\t\t\tend\n\t\tend\n\tend\nend\n\nfunction ShopService.Remove(player)\n\tlastHatch[player] = nil\nend\n\nreturn ShopService\n" i8.Parent=i5 i5.Parent=game:GetService("ServerScriptService") if SP:FindFirstChild("ClientMain") then SP["ClientMain"]:Destroy() end if SP:FindFirstChild("UI") then SP["UI"]:Destroy() end local i9=Instance.new("LocalScript") i9.Name="ClientMain" i9.Source="--[[\n\tClientMain  (LocalScript in StarterPlayerScripts)\n\n\tThe \"boss\" of the player's screen. It:\n\t  1. builds the UI using the modules in the UI folder\n\t  2. sends the player's clicks to the server (FireServer)\n\t  3. listens for the server's updates and passes them to the UI (OnClientEvent)\n\n\tIt does NOT decide coins or damage; the server does that.\n]]\n\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal MarketplaceService = game:GetService(\"MarketplaceService\")\n\nlocal player = Players.LocalPlayer\nlocal Remotes = ReplicatedStorage:WaitForChild(\"Remotes\") -- made by GameServer. WaitForChild = wait until it exists\n\n-- The UI modules (they live in the \"UI\" folder next to this script)\nlocal UI = script.Parent:WaitForChild(\"UI\")\nlocal Theme = require(UI.Theme)\nlocal Effects = require(UI.Effects)\nlocal HUD = require(UI.HUD)\nlocal Panels = require(UI.Panels)\n\nlocal C = Theme.Colors\n\n---------------------------------------------------------------------------\n-- 1. BUILD THE SCREEN\n---------------------------------------------------------------------------\nlocal gui = Instance.new(\"ScreenGui\")\ngui.Name = \"GameUI\"\ngui.ResetOnSpawn = false   -- keep the UI if the character respawns\ngui.IgnoreGuiInset = true  -- cover the WHOLE screen\ngui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling\ngui.Parent = player:WaitForChild(\"PlayerGui\")\n\nEffects.Init(gui)\nlocal buttons = HUD.Build(gui) -- gives back { Attack, Shop, Eggs, Story }\n\nlocal isHatching = false -- true while the egg animation is playing\n\n-- \"actions\" = what the windows' buttons should do. Panels calls these.\nlocal actions = {}\n\nfunction actions.BuyUpgrade(upgradeId)\n\tRemotes.BuyUpgrade:FireServer(upgradeId) -- ask the server; it checks the price and answers with DataUpdated\nend\n\nfunction actions.HatchEgg(eggId)\n\tif isHatching then return end -- wait for the current egg to finish\n\tRemotes.HatchEgg:FireServer(eggId)\nend\n\nfunction actions.BuyPass(passId)\n\tif passId == 0 then\n\t\tEffects.Toast(\"Set this gamepass's PassId in GameConfig!\", C.Red)\n\t\treturn\n\tend\n\tMarketplaceService:PromptGamePassPurchase(player, passId) -- opens Roblox's buy window\nend\n\nPanels.Build(gui, actions)\n\n---------------------------------------------------------------------------\n-- 2. BUTTONS -> SERVER\n-- .Activated fires when the button is clicked OR tapped (works on phones too)\n---------------------------------------------------------------------------\nbuttons.Attack.Activated:Connect(function()\n\tHUD.HeroAttack()             -- animate right away so it feels instant...\n\tRemotes.Attack:FireServer()  -- ...while the server does the real damage\nend)\n\nbuttons.Shop.Activated:Connect(function() Panels.Open(\"Shop\") end)\nbuttons.Eggs.Activated:Connect(function() Panels.Open(\"Eggs\") end)\nbuttons.Story.Activated:Connect(function() Panels.Open(\"Story\") end)\n\n---------------------------------------------------------------------------\n-- 3. SERVER -> SCREEN\n-- Each OnClientEvent function receives exactly what the server put in FireClient(player, ...)\n---------------------------------------------------------------------------\nRemotes.DataUpdated.OnClientEvent:Connect(function(data)\n\tHUD.UpdateData(data)\n\tPanels.UpdateData(data)\nend)\n\nRemotes.EnemyUpdated.OnClientEvent:Connect(HUD.SetEnemy)       -- (info)\nRemotes.EnemyHit.OnClientEvent:Connect(HUD.EnemyHit)           -- (info)\nRemotes.EnemyDefeated.OnClientEvent:Connect(HUD.EnemyDefeated) -- (rewards)\n\nRemotes.Hatched.OnClientEvent:Connect(function(characterId)\n\tisHatching = true\n\tPanels.Close()                    -- hide the egg window during the show\n\tEffects.PlayHatch(characterId)    -- this waits until the animation is done\n\tisHatching = false\nend)\n\n-- kind = \"Good\", \"Bad\" or \"Level\" (picks the color)\nlocal NOTIFY_COLORS = { Good = C.Green, Bad = C.Red, Level = C.Gold }\nRemotes.Notify.OnClientEvent:Connect(function(message, kind)\n\tEffects.Toast(message, NOTIFY_COLORS[kind])\nend)\n\n---------------------------------------------------------------------------\n-- 4. TELL THE SERVER WE'RE READY\n-- Everything above is hooked up, so now ask for our data + enemy.\n---------------------------------------------------------------------------\nRemotes.Ready:FireServer()\n" i9.Parent=SP local i10=Instance.new("Folder") i10.Name="UI" local i11=Instance.new("ModuleScript") i11.Name="Effects" i11.Source="--[[\n\tEffects  (ModuleScript in StarterPlayerScripts > UI)\n\n\tThe \"juice\": damage numbers, shakes, flashes, messages and the egg hatch scene.\n\tCall Effects.Init(gui) once before using anything else.\n]]\n\nlocal TweenService = game:GetService(\"TweenService\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n\nlocal GameConfig = require(ReplicatedStorage.Shared.GameConfig)\nlocal Theme = require(script.Parent.Theme)\nlocal UIKit = require(script.Parent.UIKit)\n\nlocal Effects = {}\nlocal C = Theme.Colors\nlocal gui = nil -- the ScreenGui, set in Init\nlocal toastLabel = nil\n\nfunction Effects.Init(screenGui)\n\tgui = screenGui\n\n\t-- The message (\"toast\") that drops in from the top of the screen\n\ttoastLabel = UIKit.Label(gui, \"\", UDim2.new(0.5, 0, 0.055, 0), UDim2.new(0.5, 0, -0.1, 0))\n\ttoastLabel.ZIndex = 50\nend\n\n-- Toast(text, color): show a short message for about 2 seconds\nfunction Effects.Toast(text, color)\n\ttoastLabel.Text = text\n\ttoastLabel.TextColor3 = color or C.Text\n\ttoastLabel.Position = UDim2.new(0.5, 0, -0.1, 0) -- start above the screen\n\tUIKit.Tween(toastLabel, 0.35, { Position = UDim2.new(0.5, 0, 0.27, 0) }, Enum.EasingStyle.Back)\n\tUIKit.Pop(toastLabel, 1.3)\n\ttask.delay(1.8, function() -- task.delay(seconds, function) = run this later, without pausing now\n\t\tif toastLabel.Text == text then -- only hide it if no newer message replaced it\n\t\t\tUIKit.Tween(toastLabel, 0.3, { Position = UDim2.new(0.5, 0, -0.1, 0) }, Enum.EasingStyle.Back, Enum.EasingDirection.In)\n\t\tend\n\tend)\nend\n\n-- FloatText(parent, text, color, big): a number that pops up, drifts upward and fades away\nfunction Effects.FloatText(parent, text, color, big)\n\tlocal x = 0.3 + math.random() * 0.4 -- random spot between 30% and 70% across\n\tlocal height = big and 0.16 or 0.11\n\tlocal label = UIKit.Label(parent, text, UDim2.new(0.7, 0, height, 0), UDim2.new(x, 0, 0.45, 0), color)\n\tlabel.ZIndex = 10\n\tlabel.Rotation = math.random(-12, 12)\n\tUIKit.Pop(label, 1.7)\n\n\tlocal goal = UDim2.new(x, 0, 0.15, 0) -- float up\n\tUIKit.Tween(label, 0.8, { Position = goal, TextTransparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)\n\tUIKit.Tween(label:FindFirstChildOfClass(\"UIStroke\"), 0.8, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)\n\ttask.delay(0.8, function()\n\t\tlabel:Destroy() -- clean up, or thousands of invisible labels would pile up\n\tend)\nend\n\n-- Shake(object, strength): wiggle left and right quickly\nfunction Effects.Shake(object, strength)\n\tstrength = strength or 5\n\ttask.spawn(function() -- run on the side, so the code that called Shake doesn't wait\n\t\tfor i = 1, 4 do\n\t\t\tobject.Rotation = (i % 2 == 0) and strength or -strength -- even = right, odd = left\n\t\t\ttask.wait(0.03)\n\t\tend\n\t\tobject.Rotation = 0\n\tend)\nend\n\n-- Flash(frame): flash a frame white for a moment (when something gets hit)\nfunction Effects.Flash(frame)\n\tframe.BackgroundTransparency = 0.25\n\tUIKit.Tween(frame, 0.25, { BackgroundTransparency = 1 })\nend\n\n--[[\n\tPlayHatch(characterId)\n\tThe big egg scene: screen darkens, egg wobbles faster and faster, white flash,\n\tthen the character card bursts out with spinning rays behind it.\n\tThis function WAITS until the scene is over (about 4 seconds).\n]]\nfunction Effects.PlayHatch(characterId)\n\tlocal character = nil\n\tfor _, item in ipairs(GameConfig.Characters) do\n\t\tif item.Id == characterId then\n\t\t\tcharacter = item\n\t\tend\n\tend\n\tif not character then return end\n\tlocal rarityColor = GameConfig.RarityColors[character.Rarity]\n\n\t-- dark cover over the whole screen\n\tlocal overlay = UIKit.Create(\"Frame\", {\n\t\tSize = UDim2.new(1, 0, 1, 0),\n\t\tBackgroundColor3 = C.Outline,\n\t\tBackgroundTransparency = 1,\n\t\tZIndex = 60,\n\t}, gui)\n\tUIKit.Tween(overlay, 0.3, { BackgroundTransparency = 0.25 })\n\n\t-- the egg (a tall rounded box)\n\tlocal egg = UIKit.Create(\"Frame\", {\n\t\tSize = UDim2.new(0.2, 0, 0.27, 0),\n\t\tSizeConstraint = Enum.SizeConstraint.RelativeYY, -- size is based on screen HEIGHT, so it stays egg-shaped\n\t\tPosition = UDim2.new(0.5, 0, 0.5, 0),\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\tBackgroundColor3 = Color3.new(1, 1, 1),\n\t\tZIndex = 61,\n\t}, overlay)\n\tUIKit.Corner(egg, 999) -- a huge radius = fully rounded\n\tUIKit.Outline(egg, 5)\n\tUIKit.Gradient(egg, Color3.fromRGB(255, 250, 235), C.Gold)\n\tUIKit.Pop(egg, 0.2) -- grow in from tiny\n\n\t-- wobble, faster each time\n\tfor i = 1, 10 do\n\t\tlocal speed = 0.17 - i * 0.012\n\t\tUIKit.Tween(egg, speed, { Rotation = (i % 2 == 0) and 14 or -14 })\n\t\ttask.wait(speed)\n\tend\n\n\t-- WHITE FLASH\n\tlocal flash = UIKit.Create(\"Frame\", {\n\t\tSize = UDim2.new(1, 0, 1, 0),\n\t\tBackgroundColor3 = Color3.new(1, 1, 1),\n\t\tZIndex = 70,\n\t}, overlay)\n\tUIKit.Tween(flash, 0.6, { BackgroundTransparency = 1 })\n\tegg:Destroy()\n\n\t-- spinning rays behind the card\n\tlocal rays = UIKit.Create(\"Frame\", {\n\t\tSize = UDim2.new(0.8, 0, 0.8, 0),\n\t\tSizeConstraint = Enum.SizeConstraint.RelativeYY,\n\t\tPosition = UDim2.new(0.5, 0, 0.5, 0),\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\tBackgroundTransparency = 1,\n\t\tZIndex = 61,\n\t}, overlay)\n\tfor i = 1, 6 do\n\t\tUIKit.Create(\"Frame\", {\n\t\t\tSize = UDim2.new(0.1, 0, 1, 0),\n\t\t\tPosition = UDim2.new(0.5, 0, 0.5, 0),\n\t\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\t\tRotation = i * 30, -- 6 rays, 30 degrees apart (each ray pokes out both sides = 12 points)\n\t\t\tBackgroundColor3 = rarityColor,\n\t\t\tBackgroundTransparency = 0.6,\n\t\t\tZIndex = 61,\n\t\t}, rays)\n\tend\n\tlocal spinForever = TweenInfo.new(5, Enum.EasingStyle.Linear, Enum.EasingDirection.In, -1) -- -1 = repeat forever\n\tTweenService:Create(rays, spinForever, { Rotation = 360 }):Play()\n\n\t-- the character card\n\tlocal card = UIKit.Panel(overlay, UDim2.new(0.26, 0, 0.38, 0), UDim2.new(0.5, 0, 0.5, 0), C.Panel)\n\tcard.SizeConstraint = Enum.SizeConstraint.RelativeYY\n\tcard.ZIndex = 62\n\tcard:FindFirstChildOfClass(\"UIStroke\").Color = rarityColor -- outline in the rarity color\n\tcard:FindFirstChildOfClass(\"UIStroke\").Thickness = 5\n\n\tlocal rarityLabel = UIKit.Label(card, string.upper(character.Rarity), UDim2.new(0.8, 0, 0.11, 0), UDim2.new(0.5, 0, 0.1, 0), rarityColor)\n\trarityLabel.ZIndex = 63\n\n\tlocal picture = UIKit.Create(\"ImageLabel\", { -- BLANK picture. Put \"rbxassetid://123\" in Image later!\n\t\tImage = \"\",\n\t\tSize = UDim2.new(0.75, 0, 0.52, 0),\n\t\tPosition = UDim2.new(0.5, 0, 0.45, 0),\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\tBackgroundColor3 = C.Slot,\n\t\tZIndex = 63,\n\t}, card)\n\tUIKit.Corner(picture)\n\n\tlocal nameLabel = UIKit.Label(card, character.Name, UDim2.new(0.9, 0, 0.12, 0), UDim2.new(0.5, 0, 0.79, 0))\n\tnameLabel.ZIndex = 63\n\tlocal powerLabel = UIKit.Label(card, \"+\" .. character.Power .. \" POWER\", UDim2.new(0.6, 0, 0.08, 0), UDim2.new(0.5, 0, 0.9, 0), C.Gold, Theme.TextFont)\n\tpowerLabel.ZIndex = 63\n\n\tUIKit.Pop(card, 0.1) -- burst out\n\ttask.wait(2.4) -- let them look at it\n\n\tUIKit.Tween(UIKit.GetScale(card), 0.25, { Scale = 0 }, Enum.EasingStyle.Back, Enum.EasingDirection.In)\n\tUIKit.Tween(overlay, 0.3, { BackgroundTransparency = 1 })\n\trays.Visible = false\n\ttask.wait(0.3)\n\toverlay:Destroy() -- removes everything inside it too\nend\n\nreturn Effects\n" i11.Parent=i10 local i12=Instance.new("ModuleScript") i12.Name="HUD" i12.Source="--[[\n\tHUD  (ModuleScript in StarterPlayerScripts > UI)\n\n\tThe main game screen (HUD = \"heads-up display\"):\n\t  top    : coins, gems, level + XP bar, stage banner\n\t  left   : menu buttons + YOUR character card\n\t  right  : the ENEMY card\n\t  middle : VS + the big ATTACK button\n\n\tFunctions other scripts use:\n\t  HUD.Build(gui)            make everything (call once)\n\t  HUD.UpdateData(data)      refresh coins/gems/level/stats\n\t  HUD.SetEnemy(info)        show a new enemy\n\t  HUD.EnemyHit(info)        enemy took damage\n\t  HUD.EnemyDefeated(info)   enemy died\n\t  HUD.HeroAttack()          hero lunge animation\n]]\n\nlocal TweenService = game:GetService(\"TweenService\")\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n\nlocal Formulas = require(ReplicatedStorage.Shared.Formulas)\nlocal GameConfig = require(ReplicatedStorage.Shared.GameConfig)\nlocal Theme = require(script.Parent.Theme)\nlocal UIKit = require(script.Parent.UIKit)\nlocal Effects = require(script.Parent.Effects)\n\nlocal HUD = {}\nlocal C = Theme.Colors\n\n-- Things we need to change later get saved in these variables during Build()\nlocal coinsText, gemsText, levelText, xpBar\nlocal stageTitle, stageSubtitle, stageBanner\nlocal hero, enemy\nlocal teamText\n\nlocal HERO_X = 0.3   -- where the hero card sits (30% across the screen)\nlocal ENEMY_X = 0.72 -- where the enemy card sits\n\n---------------------------------------------------------------------------\n-- small builders used only in this file\n---------------------------------------------------------------------------\n\n-- makeCurrency(parent, iconText, iconColor, order): a stat pill like [$] 1.2K\nlocal function makeCurrency(parent, iconText, iconColor, order)\n\tlocal pill = UIKit.Panel(parent, UDim2.new(0.3, 0, 1, 0), UDim2.new(0, 0, 0, 0))\n\tpill.LayoutOrder = order -- UIListLayout puts lower numbers first\n\tpill.AnchorPoint = Vector2.new(0, 0) -- the list layout places it, so measure from the top-left\n\tpill:FindFirstChildOfClass(\"UICorner\").CornerRadius = UDim.new(1, 0) -- fully rounded ends = pill shape\n\n\tlocal icon = UIKit.Create(\"TextLabel\", {\n\t\tSize = UDim2.new(1.15, 0, 1.15, 0),\n\t\tSizeConstraint = Enum.SizeConstraint.RelativeYY, -- a perfect circle based on the pill's height\n\t\tPosition = UDim2.new(0, -6, 0.5, 0),\n\t\tAnchorPoint = Vector2.new(0, 0.5),\n\t\tBackgroundColor3 = iconColor,\n\t\tText = iconText,\n\t\tFont = Theme.TitleFont,\n\t\tTextScaled = true,\n\t\tTextColor3 = C.Text,\n\t}, pill)\n\tUIKit.Corner(icon, 999)\n\tUIKit.Outline(icon)\n\tUIKit.TextOutline(icon)\n\tUIKit.Create(\"UIPadding\", { PaddingTop = UDim.new(0.2, 0), PaddingBottom = UDim.new(0.2, 0) }, icon)\n\n\treturn UIKit.Label(pill, \"0\", UDim2.new(0.6, 0, 0.62, 0), UDim2.new(0.6, 0, 0.5, 0))\nend\n\n-- makeFighterCard(x, title): the big card for the hero or the enemy\nlocal function makeFighterCard(parent, x, title)\n\tlocal card = UIKit.Panel(parent, UDim2.new(0.22, 0, 0.5, 0), UDim2.new(x, 0, 0.55, 0))\n\tUIKit.Create(\"UIAspectRatioConstraint\", { AspectRatio = 0.78 }, card) -- keep the same shape on every screen\n\n\tlocal nameLabel = UIKit.Label(card, title, UDim2.new(0.9, 0, 0.1, 0), UDim2.new(0.5, 0, 0.09, 0))\n\n\t-- the picture slot. BLANK for now: set Image = \"rbxassetid://YOUR_ID\" later\n\tlocal picture = UIKit.Create(\"ImageLabel\", {\n\t\tImage = \"\",\n\t\tSize = UDim2.new(0.84, 0, 0.62, 0),\n\t\tPosition = UDim2.new(0.5, 0, 0.5, 0),\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\tBackgroundColor3 = C.Slot,\n\t\tScaleType = Enum.ScaleType.Fit,\n\t}, card)\n\tUIKit.Corner(picture)\n\tUIKit.Outline(picture, 2)\n\n\tlocal flash = UIKit.Create(\"Frame\", { -- white overlay we flash when hit\n\t\tSize = UDim2.new(1, 0, 1, 0),\n\t\tBackgroundColor3 = Color3.new(1, 1, 1),\n\t\tBackgroundTransparency = 1,\n\t\tZIndex = 5,\n\t}, picture)\n\tUIKit.Corner(flash)\n\n\t-- idle \"breathing\": gently float up and down forever\n\tlocal bob = TweenInfo.new(1.3, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true) -- -1 = forever, true = go back and forth\n\tTweenService:Create(picture, bob, { Position = UDim2.new(0.5, 0, 0.47, 0) }):Play()\n\n\treturn { Frame = card, Name = nameLabel, Picture = picture, Flash = flash }\nend\n\n---------------------------------------------------------------------------\n-- BUILD\n---------------------------------------------------------------------------\nfunction HUD.Build(gui)\n\t-- BACKGROUND: dark blue gradient\n\tlocal background = UIKit.Create(\"Frame\", {\n\t\tSize = UDim2.new(1, 0, 1, 0),\n\t\tBackgroundColor3 = Color3.new(1, 1, 1),\n\t\tZIndex = 0,\n\t}, gui)\n\tUIKit.Gradient(background, C.BackgroundTop, C.BackgroundBottom)\n\n\t-- faint dots slowly rising (makes the background feel alive)\n\tfor _ = 1, 16 do\n\t\tlocal size = math.random(12, 50)\n\t\tlocal dot = UIKit.Create(\"Frame\", {\n\t\t\tSize = UDim2.new(0, size, 0, size),\n\t\t\tPosition = UDim2.new(math.random(), 0, 1.1, 0),\n\t\t\tBackgroundColor3 = Color3.new(1, 1, 1),\n\t\t\tBackgroundTransparency = 0.93,\n\t\t}, background)\n\t\tUIKit.Corner(dot, 999)\n\t\tlocal rise = TweenInfo.new(math.random(10, 20), Enum.EasingStyle.Linear, Enum.EasingDirection.In, -1)\n\t\ttask.delay(math.random() * 10, function() -- start at random times so they spread out\n\t\t\tTweenService:Create(dot, rise, { Position = UDim2.new(dot.Position.X.Scale, 0, -0.1, 0) }):Play()\n\t\tend)\n\tend\n\n\t-- TOP BAR: coins, gems, level (side by side)\n\tlocal topBar = UIKit.Create(\"Frame\", {\n\t\tSize = UDim2.new(0.5, 0, 0.065, 0),\n\t\tPosition = UDim2.new(0.5, 0, 0.03, 0),\n\t\tAnchorPoint = Vector2.new(0.5, 0),\n\t\tBackgroundTransparency = 1,\n\t}, gui)\n\tUIKit.Create(\"UIListLayout\", {\n\t\tFillDirection = Enum.FillDirection.Horizontal,\n\t\tHorizontalAlignment = Enum.HorizontalAlignment.Center,\n\t\tSortOrder = Enum.SortOrder.LayoutOrder,\n\t\tPadding = UDim.new(0.04, 0),\n\t}, topBar)\n\tcoinsText = makeCurrency(topBar, \"$\", C.Gold, 1)\n\tgemsText = makeCurrency(topBar, \"G\", C.Cyan, 2)\n\tlevelText = makeCurrency(topBar, \"LV\", C.PanelLight, 3)\n\n\txpBar = UIKit.Bar(gui, UDim2.new(0.3, 0, 0.028, 0), UDim2.new(0.5, 0, 0.125, 0), C.Gold)\n\n\t-- STAGE BANNER\n\tstageBanner = UIKit.Panel(gui, UDim2.new(0.3, 0, 0.085, 0), UDim2.new(0.5, 0, 0.2, 0))\n\tstageTitle = UIKit.Label(stageBanner, \"STAGE 1\", UDim2.new(0.9, 0, 0.5, 0), UDim2.new(0.5, 0, 0.36, 0), C.Gold)\n\tstageSubtitle = UIKit.Label(stageBanner, \"\", UDim2.new(0.9, 0, 0.3, 0), UDim2.new(0.5, 0, 0.74, 0), C.TextDim, Theme.TextFont)\n\n\t-- FIGHTER CARDS\n\thero = makeFighterCard(gui, HERO_X, Players.LocalPlayer.DisplayName)\n\thero.Stats = UIKit.Label(hero.Frame, \"\", UDim2.new(0.9, 0, 0.08, 0), UDim2.new(0.5, 0, 0.9, 0), C.Gold, Theme.TextFont)\n\n\tenemy = makeFighterCard(gui, ENEMY_X, \"???\")\n\tenemy.Bar = UIKit.Bar(enemy.Frame, UDim2.new(0.84, 0, 0.08, 0), UDim2.new(0.5, 0, 0.9, 0), C.Red)\n\tenemy.BossTag = UIKit.Label(enemy.Frame, \"BOSS\", UDim2.new(0.5, 0, 0.1, 0), UDim2.new(0.5, 0, -0.06, 0), C.Gold)\n\tenemy.BossTag.Visible = false\n\n\t-- VS (pulses forever)\n\tlocal vs = UIKit.Label(gui, \"VS\", UDim2.new(0.1, 0, 0.1, 0), UDim2.new(0.51, 0, 0.5, 0), C.Gold)\n\tvs.Rotation = -8\n\tlocal pulse = TweenInfo.new(0.7, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true)\n\tTweenService:Create(UIKit.GetScale(vs), pulse, { Scale = 1.15 }):Play()\n\n\tteamText = UIKit.Label(gui, \"\", UDim2.new(0.2, 0, 0.03, 0), UDim2.new(0.51, 0, 0.6, 0), C.TextDim, Theme.TextFont)\n\n\t-- ATTACK BUTTON (the only big gold button = the main thing to press)\n\tlocal attack, attackHolder = UIKit.Button(gui, \"ATTACK!\", C.Gold, UDim2.new(0.2, 0, 0.12, 0), UDim2.new(0.51, 0, 0.88, 0))\n\tUIKit.Create(\"UIAspectRatioConstraint\", { AspectRatio = 3 }, attackHolder)\n\tlocal breathe = TweenInfo.new(0.9, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true)\n\tTweenService:Create(attackHolder, breathe, { Rotation = 2 }):Play() -- gentle tilt so it draws the eye\n\n\t-- MENU BUTTONS on the left edge\n\tlocal menu = {}\n\tlocal menuNames = { \"SHOP\", \"EGGS\", \"STORY\" }\n\tfor index, name in ipairs(menuNames) do\n\t\tlocal y = 0.4 + (index - 1) * 0.13 -- stack them downward: 0.40, 0.53, 0.66\n\t\tlocal button, holder = UIKit.Button(gui, name, C.PanelLight, UDim2.new(0.1, 0, 0.1, 0), UDim2.new(0.08, 0, y, 0))\n\t\tUIKit.Create(\"UIAspectRatioConstraint\", { AspectRatio = 1.6 }, holder)\n\t\tmenu[name] = button\n\tend\n\n\t-- give the buttons back so ClientMain can hook them up\n\treturn {\n\t\tAttack = attack,\n\t\tShop = menu.SHOP,\n\t\tEggs = menu.EGGS,\n\t\tStory = menu.STORY,\n\t}\nend\n\n---------------------------------------------------------------------------\n-- UPDATES\n---------------------------------------------------------------------------\n\n-- UpdateData(data): refresh every number that comes from the player's data\nfunction HUD.UpdateData(data)\n\tlocal oldCoins = coinsText.Text\n\tcoinsText.Text = Formulas.FormatNumber(data.Coins)\n\tgemsText.Text = Formulas.FormatNumber(data.Gems)\n\tif coinsText.Text ~= oldCoins then\n\t\tUIKit.Pop(coinsText.Parent, 1.12) -- boing the pill when the number changes\n\tend\n\n\tlocal oldLevel = levelText.Text\n\tlevelText.Text = tostring(data.Level)\n\tif oldLevel ~= \"0\" and oldLevel ~= levelText.Text then\n\t\tUIKit.Pop(levelText.Parent, 1.3)\n\tend\n\n\tlocal needed = Formulas.XPNeeded(data.Level)\n\tUIKit.SetBar(xpBar, data.XP / needed, \"XP \" .. data.XP .. \" / \" .. needed)\n\n\thero.Stats.Text = \"DMG \" .. Formulas.FormatNumber(Formulas.ClickDamage(data))\n\t\t.. \"   AUTO \" .. Formulas.FormatNumber(Formulas.AutoDamage(data)) .. \"/s\"\n\tteamText.Text = \"TEAM: \" .. #data.Team .. \"  |  POWER \" .. Formulas.FormatNumber(Formulas.TeamPower(data))\nend\n\n-- SetEnemy(info): a new enemy arrives (info comes from the server)\nfunction HUD.SetEnemy(info)\n\tenemy.Name.Text = info.Name\n\tenemy.BossTag.Visible = info.IsBoss\n\tenemy.Frame:FindFirstChildOfClass(\"UIStroke\").Color = info.IsBoss and C.Gold or C.Outline -- gold outline for bosses\n\tUIKit.SetBar(enemy.Bar, info.Health / info.MaxHealth, Formulas.FormatNumber(info.Health) .. \" / \" .. Formulas.FormatNumber(info.MaxHealth))\n\n\tlocal stageInChapter = (info.Stage - 1) % GameConfig.StagesPerChapter + 1\n\tstageTitle.Text = info.IsBoss and \"BOSS FIGHT!\" or (\"STAGE \" .. stageInChapter .. \" / \" .. GameConfig.StagesPerChapter)\n\tstageTitle.TextColor3 = info.IsBoss and C.Red or C.Gold\n\tstageSubtitle.Text = \"CHAPTER \" .. info.ChapterNumber .. \"  -  \" .. string.upper(info.ChapterName)\n\tUIKit.Pop(stageBanner, 1.15)\n\n\t-- drop-in animation: start tiny and tilted, spring to full size\n\tlocal scale = UIKit.GetScale(enemy.Frame)\n\tscale.Scale = 0\n\tenemy.Frame.Rotation = 15\n\tUIKit.Tween(scale, 0.45, { Scale = info.IsBoss and 1.08 or 1 }, Enum.EasingStyle.Back)\n\tUIKit.Tween(enemy.Frame, 0.45, { Rotation = 0 }, Enum.EasingStyle.Back)\nend\n\n-- EnemyHit(info): show damage. info = { Damage, Health, MaxHealth, IsAuto }\nfunction HUD.EnemyHit(info)\n\tUIKit.SetBar(enemy.Bar, info.Health / info.MaxHealth, Formulas.FormatNumber(info.Health) .. \" / \" .. Formulas.FormatNumber(info.MaxHealth))\n\tEffects.FloatText(enemy.Frame, \"-\" .. Formulas.FormatNumber(info.Damage), info.IsAuto and C.TextDim or C.Text)\n\tEffects.Flash(enemy.Flash)\n\tEffects.Shake(enemy.Frame, info.IsAuto and 3 or 6)\n\tif info.IsAuto then\n\t\tHUD.HeroAttack() -- show the hero swinging on auto hits too\n\tend\nend\n\n-- EnemyDefeated(info): rewards popup + the enemy spins away\nfunction HUD.EnemyDefeated(info)\n\tEffects.FloatText(enemy.Frame, \"+\" .. Formulas.FormatNumber(info.Coins) .. \" COINS\", C.Gold, true)\n\tif info.Gems > 0 then\n\t\tEffects.FloatText(enemy.Frame, \"+\" .. info.Gems .. \" GEMS\", C.Cyan, true)\n\tend\n\tif info.WasBoss then\n\t\tEffects.Toast(\"BOSS DEFEATED!\", C.Gold)\n\tend\n\tUIKit.Tween(UIKit.GetScale(enemy.Frame), 0.35, { Scale = 0 }, Enum.EasingStyle.Back, Enum.EasingDirection.In)\n\tUIKit.Tween(enemy.Frame, 0.35, { Rotation = -30 })\nend\n\n-- HeroAttack(): the hero card jumps toward the enemy and bounces back\nfunction HUD.HeroAttack()\n\tlocal frame = hero.Frame\n\tUIKit.Tween(frame, 0.07, { Position = UDim2.new(HERO_X + 0.04, 0, 0.55, 0), Rotation = 5 })\n\ttask.delay(0.08, function()\n\t\tUIKit.Tween(frame, 0.3, { Position = UDim2.new(HERO_X, 0, 0.55, 0), Rotation = 0 }, Enum.EasingStyle.Back)\n\tend)\nend\n\nreturn HUD\n" i12.Parent=i10 local i13=Instance.new("ModuleScript") i13.Name="Panels" i13.Source="--[[\n\tPanels  (ModuleScript in StarterPlayerScripts > UI)\n\n\tThe pop-up windows: SHOP, EGGS and STORY.\n\tThis file only DRAWS them. When a button is pressed, it calls one of\n\tthe \"actions\" that ClientMain hands in, and ClientMain talks to the server.\n\n\tFunctions:\n\t  Panels.Build(gui, actions)   make all windows (call once)\n\t  Panels.Open(name)            open \"Shop\", \"Eggs\" or \"Story\"\n\t  Panels.UpdateData(data)      refresh prices, team and story progress\n]]\n\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n\nlocal GameConfig = require(ReplicatedStorage.Shared.GameConfig)\nlocal Formulas = require(ReplicatedStorage.Shared.Formulas)\nlocal Theme = require(script.Parent.Theme)\nlocal UIKit = require(script.Parent.UIKit)\n\nlocal Panels = {}\nlocal C = Theme.Colors\n\nlocal windows = {}       -- windows.Shop, windows.Eggs, windows.Story\nlocal openWindow = nil   -- the window that's open right now (nil = none)\nlocal upgradeRows = {}   -- so we can update prices later\nlocal passRows = {}\nlocal chapterRows = {}\nlocal teamGrid = nil\n\n---------------------------------------------------------------------------\n-- builders\n---------------------------------------------------------------------------\n\n-- makeWindow(title): a centered window with a title, close button and a scrolling list\nlocal function makeWindow(gui, title)\n\tlocal window = UIKit.Panel(gui, UDim2.new(0.5, 0, 0.66, 0), UDim2.new(0.5, 0, 0.52, 0))\n\twindow.Visible = false\n\twindow.ZIndex = 20 -- above the HUD\n\tUIKit.Create(\"UIAspectRatioConstraint\", { AspectRatio = 1.3 }, window)\n\twindow:FindFirstChildOfClass(\"UIStroke\").Thickness = 5\n\n\tUIKit.Label(window, title, UDim2.new(0.6, 0, 0.1, 0), UDim2.new(0.5, 0, 0.08, 0), C.Gold)\n\n\tlocal close, closeHolder = UIKit.Button(window, \"X\", C.Red, UDim2.new(0.11, 0, 0.11, 0), UDim2.new(0.97, 0, 0.03, 0))\n\tcloseHolder.SizeConstraint = Enum.SizeConstraint.RelativeYY -- keep it square\n\tclose.Activated:Connect(function()\n\t\tPanels.Close()\n\tend)\n\n\tlocal list = UIKit.Create(\"ScrollingFrame\", {\n\t\tSize = UDim2.new(0.94, 0, 0.8, 0),\n\t\tPosition = UDim2.new(0.5, 0, 0.57, 0),\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\tBackgroundTransparency = 1,\n\t\tBorderSizePixel = 0,\n\t\tScrollBarThickness = 8,\n\t\tScrollBarImageColor3 = C.PanelLight,\n\t\tCanvasSize = UDim2.new(0, 0, 0, 0),\n\t\tAutomaticCanvasSize = Enum.AutomaticSize.Y, -- the scroll area grows as we add rows\n\t}, window)\n\tUIKit.Create(\"UIListLayout\", { Padding = UDim.new(0, 10), SortOrder = Enum.SortOrder.LayoutOrder, HorizontalAlignment = Enum.HorizontalAlignment.Center }, list)\n\tUIKit.Create(\"UIPadding\", { PaddingTop = UDim.new(0, 8), PaddingBottom = UDim.new(0, 8) }, list)\n\n\treturn window, list\nend\n\n-- makeHeader(list, text, order): a small section title inside a list\nlocal function makeHeader(list, text, order)\n\tlocal header = UIKit.Label(list, text, UDim2.new(0.95, 0, 0, 32), UDim2.new(0, 0, 0, 0), C.TextDim)\n\theader.TextXAlignment = Enum.TextXAlignment.Left\n\theader.AnchorPoint = Vector2.new(0, 0) -- the list layout places it, so measure from the top-left\n\theader.LayoutOrder = order\n\treturn header\nend\n\n--[[\n\tmakeRow(list, title, description, buttonText, buttonColor, order)\n\tOne row: [picture] Title / description  [BUTTON]\n\tGives back a table: { Frame, Description, Button, ButtonLabel }\n]]\nlocal function makeRow(list, title, description, buttonText, buttonColor, order)\n\tlocal row = UIKit.Panel(list, UDim2.new(0.97, 0, 0, 84), UDim2.new(0, 0, 0, 0), C.PanelLight)\n\trow.LayoutOrder = order\n\trow.AnchorPoint = Vector2.new(0, 0) -- the list layout places it, so measure from the top-left\n\n\tlocal icon = UIKit.Create(\"ImageLabel\", { -- BLANK icon. Put an image id in Image later.\n\t\tImage = \"\",\n\t\tSize = UDim2.new(0, 64, 0, 64),\n\t\tPosition = UDim2.new(0, 10, 0.5, 0),\n\t\tAnchorPoint = Vector2.new(0, 0.5),\n\t\tBackgroundColor3 = C.Slot,\n\t}, row)\n\tUIKit.Corner(icon, 12)\n\tUIKit.Outline(icon, 2)\n\n\tlocal titleLabel = UIKit.Label(row, title, UDim2.new(0.5, 0, 0.36, 0), UDim2.new(0, 86, 0.32, 0))\n\ttitleLabel.AnchorPoint = Vector2.new(0, 0.5) -- measure from the LEFT edge instead of the center\n\ttitleLabel.TextXAlignment = Enum.TextXAlignment.Left\n\n\tlocal descLabel = UIKit.Label(row, description, UDim2.new(0.5, 0, 0.26, 0), UDim2.new(0, 86, 0.7, 0), C.TextDim, Theme.TextFont)\n\tdescLabel.AnchorPoint = Vector2.new(0, 0.5)\n\tdescLabel.TextXAlignment = Enum.TextXAlignment.Left\n\n\tlocal button, _, buttonLabel = UIKit.Button(row, buttonText, buttonColor, UDim2.new(0.25, 0, 0.78, 0), UDim2.new(0.85, 0, 0.5, 0))\n\n\treturn { Frame = row, Description = descLabel, Button = button, ButtonLabel = buttonLabel }\nend\n\n---------------------------------------------------------------------------\n-- BUILD\n-- actions = a table of functions ClientMain gives us:\n--   actions.BuyUpgrade(upgradeId)\n--   actions.HatchEgg(eggId)\n--   actions.BuyPass(passId)\n---------------------------------------------------------------------------\nfunction Panels.Build(gui, actions)\n\t-- SHOP ---------------------------------------------------------------\n\tlocal shop, shopList = makeWindow(gui, \"SHOP\")\n\twindows.Shop = shop\n\n\tmakeHeader(shopList, \"UPGRADES\", 1)\n\tfor index, upgrade in ipairs(GameConfig.Upgrades) do\n\t\tlocal row = makeRow(shopList, upgrade.Name, upgrade.Description, \"...\", C.Green, 1 + index)\n\t\trow.Button.Activated:Connect(function()\n\t\t\tactions.BuyUpgrade(upgrade.Id)\n\t\tend)\n\t\tupgradeRows[upgrade.Id] = row\n\tend\n\n\tmakeHeader(shopList, \"GAMEPASSES\", 100)\n\tfor index, pass in ipairs(GameConfig.Gamepasses) do\n\t\tlocal row = makeRow(shopList, pass.Name, pass.Description, \"R$ BUY\", C.Gold, 100 + index)\n\t\trow.Button.Activated:Connect(function()\n\t\t\tactions.BuyPass(pass.PassId)\n\t\tend)\n\t\tpassRows[pass.Key] = row\n\tend\n\n\t-- EGGS ---------------------------------------------------------------\n\tlocal eggs, eggList = makeWindow(gui, \"EGGS\")\n\twindows.Eggs = eggs\n\n\tfor index, egg in ipairs(GameConfig.Eggs) do\n\t\tlocal currencyText = egg.Currency == \"Gems\" and \" GEMS\" or \" COINS\"\n\t\tlocal row = makeRow(eggList, egg.Name, egg.Description, Formulas.FormatNumber(egg.Price) .. currencyText, C.Green, index)\n\t\trow.Button.Activated:Connect(function()\n\t\t\tactions.HatchEgg(egg.Id)\n\t\tend)\n\tend\n\n\tmakeHeader(eggList, \"YOUR TEAM\", 50)\n\tteamGrid = UIKit.Create(\"Frame\", {\n\t\tSize = UDim2.new(0.97, 0, 0, 0),\n\t\tAutomaticSize = Enum.AutomaticSize.Y, -- grows taller as we add characters\n\t\tBackgroundTransparency = 1,\n\t\tLayoutOrder = 51,\n\t}, eggList)\n\tUIKit.Create(\"UIGridLayout\", {\n\t\tCellSize = UDim2.new(0, 110, 0, 130),\n\t\tCellPadding = UDim2.new(0, 10, 0, 10),\n\t\tSortOrder = Enum.SortOrder.LayoutOrder,\n\t}, teamGrid)\n\n\t-- STORY --------------------------------------------------------------\n\tlocal story, storyList = makeWindow(gui, \"STORY\")\n\twindows.Story = story\n\n\tfor index, chapter in ipairs(GameConfig.Chapters) do\n\t\tlocal first = (index - 1) * GameConfig.StagesPerChapter + 1 -- chapter 2 starts at stage 11\n\t\tlocal last = index * GameConfig.StagesPerChapter            -- and ends at stage 20\n\t\tlocal row = makeRow(storyList, \"CH. \" .. index .. \"  \" .. chapter.Name, \"Stages \" .. first .. \"-\" .. last .. \"  |  Boss: \" .. chapter.Boss, \"LOCKED\", C.Slot, index)\n\t\trow.Button.Active = false -- it's just a status badge, not clickable\n\t\tchapterRows[index] = { Row = row, First = first, Last = last }\n\tend\nend\n\n---------------------------------------------------------------------------\n-- OPEN / CLOSE\n---------------------------------------------------------------------------\nfunction Panels.Open(name)\n\tlocal window = windows[name]\n\tif openWindow == window then -- pressing the same menu button again closes it\n\t\tPanels.Close()\n\t\treturn\n\tend\n\tif openWindow then\n\t\topenWindow.Visible = false -- hide the other window first\n\tend\n\topenWindow = window\n\twindow.Visible = true\n\tUIKit.Pop(window, 0.6) -- grows open with a bounce\nend\n\nfunction Panels.Close()\n\tif not openWindow then return end\n\tlocal window = openWindow\n\topenWindow = nil\n\tUIKit.Tween(UIKit.GetScale(window), 0.15, { Scale = 0.6 }, Enum.EasingStyle.Back, Enum.EasingDirection.In)\n\ttask.delay(0.15, function()\n\t\tif openWindow ~= window then -- it wasn't reopened in the meantime\n\t\t\twindow.Visible = false\n\t\tend\n\tend)\nend\n\n---------------------------------------------------------------------------\n-- UPDATE (called every time new data arrives from the server)\n---------------------------------------------------------------------------\n\n-- rebuildTeam(data): redraw the \"YOUR TEAM\" grid (one card per character type, with a count)\nlocal function rebuildTeam(data)\n\tfor _, child in ipairs(teamGrid:GetChildren()) do\n\t\tif child:IsA(\"Frame\") then\n\t\t\tchild:Destroy() -- remove the old cards\n\t\tend\n\tend\n\n\t-- count how many of each character we own. e.g. counts.NinjaKid = 3\n\tlocal counts = {}\n\tfor _, characterId in ipairs(data.Team) do\n\t\tcounts[characterId] = (counts[characterId] or 0) + 1\n\tend\n\n\tfor order, character in ipairs(GameConfig.Characters) do\n\t\tlocal count = counts[character.Id]\n\t\tif count then -- only show characters we have\n\t\t\tlocal rarityColor = GameConfig.RarityColors[character.Rarity]\n\t\t\tlocal card = UIKit.Panel(teamGrid, UDim2.new(0, 0, 0, 0), UDim2.new(0, 0, 0, 0), C.PanelLight)\n\t\t\tcard.AnchorPoint = Vector2.new(0, 0)\n\t\t\tcard.LayoutOrder = -order -- negative = rarest (last in the list) shows FIRST\n\t\t\tcard:FindFirstChildOfClass(\"UIStroke\").Color = rarityColor\n\n\t\t\tlocal picture = UIKit.Create(\"ImageLabel\", { -- BLANK picture\n\t\t\t\tImage = \"\",\n\t\t\t\tSize = UDim2.new(0.8, 0, 0.55, 0),\n\t\t\t\tPosition = UDim2.new(0.5, 0, 0.36, 0),\n\t\t\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\t\t\tBackgroundColor3 = C.Slot,\n\t\t\t}, card)\n\t\t\tUIKit.Corner(picture, 10)\n\n\t\t\tUIKit.Label(card, character.Name, UDim2.new(0.92, 0, 0.14, 0), UDim2.new(0.5, 0, 0.75, 0), C.Text, Theme.TextFont)\n\t\t\tUIKit.Label(card, \"x\" .. count, UDim2.new(0.5, 0, 0.13, 0), UDim2.new(0.5, 0, 0.9, 0), rarityColor)\n\t\tend\n\tend\nend\n\nfunction Panels.UpdateData(data)\n\t-- upgrade prices\n\tfor _, upgrade in ipairs(GameConfig.Upgrades) do\n\t\tlocal row = upgradeRows[upgrade.Id]\n\t\tlocal timesBought = data.Upgrades[upgrade.Id] or 0\n\t\tlocal cost = Formulas.UpgradeCost(upgrade, timesBought)\n\t\trow.ButtonLabel.Text = Formulas.FormatNumber(cost) .. (upgrade.Currency == \"Gems\" and \" GEMS\" or \"\")\n\t\trow.Description.Text = upgrade.Description .. \"   (owned: \" .. timesBought .. \")\"\n\tend\n\n\t-- gamepasses you own say OWNED\n\tfor key, row in pairs(passRows) do\n\t\tif data.Passes[key] then\n\t\t\trow.ButtonLabel.Text = \"OWNED\"\n\t\t\trow.Button.Active = false\n\t\tend\n\tend\n\n\t-- story progress\n\tfor _, info in ipairs(chapterRows) do\n\t\tlocal label = info.Row.ButtonLabel\n\t\tif data.Stage > info.Last then\n\t\t\tlabel.Text = \"CLEARED\"\n\t\t\tlabel.TextColor3 = C.Green\n\t\telseif data.Stage >= info.First then\n\t\t\tlabel.Text = \"NOW\"\n\t\t\tlabel.TextColor3 = C.Gold\n\t\telse\n\t\t\tlabel.Text = \"LOCKED\"\n\t\t\tlabel.TextColor3 = C.TextDim\n\t\tend\n\tend\n\n\trebuildTeam(data)\nend\n\nreturn Panels\n" i13.Parent=i10 local i14=Instance.new("ModuleScript") i14.Name="Theme" i14.Source="--[[\n\tTheme  (ModuleScript in StarterPlayerScripts > UI)\n\n\tThe LOOK of the game in one place. Change a color or font here and\n\tthe whole UI updates.\n\n\tThe color plan (on purpose, only a few colors):\n\t  - Navy blues   = backgrounds, panels, cards\n\t  - Gold         = the main action color (ATTACK, coins, XP, titles)\n\t  - Green        = \"buy\" buttons\n\t  - Red          = enemy health + close buttons\n\t  - Cyan         = gems only\n\t  - White        = text, with a dark outline\n]]\n\nlocal Theme = {}\n\n-- FONTS\n-- Want a different style? Try Enum.Font.FredokaOne, Enum.Font.Bangers, or Enum.Font.Cartoon.\nTheme.TitleFont = Enum.Font.GothamBlack -- big, heavy and bold\nTheme.TextFont = Enum.Font.GothamBold   -- normal text, a bit thinner\n\nTheme.Colors = {\n\t-- navy family\n\tBackgroundTop    = Color3.fromRGB(34, 40, 92),\n\tBackgroundBottom = Color3.fromRGB(18, 20, 48),\n\tPanel            = Color3.fromRGB(42, 50, 110),\n\tPanelLight       = Color3.fromRGB(62, 74, 150),\n\tSlot             = Color3.fromRGB(26, 30, 70),   -- empty picture slots / bar backgrounds\n\tOutline          = Color3.fromRGB(12, 14, 34),   -- the thick cartoon outline on EVERYTHING\n\n\t-- accents\n\tGold  = Color3.fromRGB(255, 196, 46),\n\tGreen = Color3.fromRGB(80, 214, 100),\n\tRed   = Color3.fromRGB(255, 76, 96),\n\tCyan  = Color3.fromRGB(70, 214, 255),\n\n\t-- text\n\tText    = Color3.fromRGB(255, 255, 255),\n\tTextDim = Color3.fromRGB(170, 180, 225),\n}\n\nTheme.OutlineThickness = 3 -- how thick the outlines are\nTheme.CornerRadius = 14    -- how round the corners are (pixels)\nTheme.ButtonDepth = 6      -- how \"3D\" buttons look (the dark part under them, in pixels)\n\nreturn Theme\n" i14.Parent=i10 local i15=Instance.new("ModuleScript") i15.Name="UIKit" i15.Source="--[[\n\tUIKit  (ModuleScript in StarterPlayerScripts > UI)\n\n\tA toolbox for BUILDING UI pieces so the other files stay short.\n\t  UIKit.Create(...)  any object\n\t  UIKit.Label(...)   outlined text\n\t  UIKit.Button(...)  chunky 3D cartoon button\n\t  UIKit.Panel(...)   a navy box with an outline\n\t  UIKit.Bar(...)     health / XP bar\n\t  UIKit.Tween / Pop  animation helpers\n\n\tSIZES AND POSITIONS: UDim2.new(scaleX, offsetX, scaleY, offsetY)\n\t  scale  = a fraction of the parent (0.5 = half)\n\t  offset = exact pixels\n\t  UDim2.new(0.5, 0, 0.1, 0) = half the parent's width, 10% of its height\n]]\n\nlocal TweenService = game:GetService(\"TweenService\")\nlocal Theme = require(script.Parent.Theme) -- script.Parent = the UI folder this file is in\n\nlocal UIKit = {}\nlocal C = Theme.Colors -- short nickname so lines don't get too long\n\n-- Create(className, properties, parent)\n--   className  = what to make, e.g. \"Frame\", \"TextLabel\", \"TextButton\"\n--   properties = a table of settings, e.g. { Text = \"Hi\", Size = ... }\n--   parent     = what it goes inside\nfunction UIKit.Create(className, properties, parent)\n\tlocal object = Instance.new(className)\n\tfor name, value in pairs(properties) do\n\t\tobject[name] = value -- same as writing object.Text = \"Hi\"\n\tend\n\tobject.Parent = parent\n\treturn object\nend\n\n-- Corner(object, radius): round the corners\nfunction UIKit.Corner(object, radius)\n\treturn UIKit.Create(\"UICorner\", { CornerRadius = UDim.new(0, radius or Theme.CornerRadius) }, object)\nend\n\n-- Outline(object, thickness): thick dark border around a BOX\nfunction UIKit.Outline(object, thickness)\n\treturn UIKit.Create(\"UIStroke\", {\n\t\tThickness = thickness or Theme.OutlineThickness,\n\t\tColor = C.Outline,\n\t\tApplyStrokeMode = Enum.ApplyStrokeMode.Border, -- Border = around the box\n\t}, object)\nend\n\n-- TextOutline(object, thickness): thick dark border around TEXT letters\nfunction UIKit.TextOutline(object, thickness)\n\treturn UIKit.Create(\"UIStroke\", {\n\t\tThickness = thickness or 2,\n\t\tColor = C.Outline,\n\t\tApplyStrokeMode = Enum.ApplyStrokeMode.Contextual, -- Contextual = around the letters\n\t}, object)\nend\n\n-- Gradient(object, topColor, bottomColor): fade from one color to another, top to bottom\nfunction UIKit.Gradient(object, topColor, bottomColor)\n\treturn UIKit.Create(\"UIGradient\", {\n\t\tColor = ColorSequence.new(topColor, bottomColor),\n\t\tRotation = 90,\n\t}, object)\nend\n\n-- Lighten / Darken a color. amount 0 = same color, 1 = fully white/black\nfunction UIKit.Lighten(color, amount)\n\treturn color:Lerp(Color3.new(1, 1, 1), amount) -- Lerp = mix two colors\nend\nfunction UIKit.Darken(color, amount)\n\treturn color:Lerp(Color3.new(0, 0, 0), amount)\nend\n\n-- GetScale(object): a UIScale lets us grow/shrink something without changing its Size\nfunction UIKit.GetScale(object)\n\treturn object:FindFirstChildOfClass(\"UIScale\") or UIKit.Create(\"UIScale\", { Scale = 1 }, object)\nend\n\n-- Tween(object, seconds, goals, style, direction): smoothly animate properties\n-- Example: UIKit.Tween(frame, 0.5, { BackgroundTransparency = 1 }) fades a frame out in half a second\nfunction UIKit.Tween(object, seconds, goals, style, direction)\n\tlocal info = TweenInfo.new(seconds, style or Enum.EasingStyle.Quad, direction or Enum.EasingDirection.Out)\n\tlocal tween = TweenService:Create(object, info, goals)\n\ttween:Play()\n\treturn tween\nend\n\n-- Pop(object, startScale): \"boing!\" Jump to startScale, then wobble back to normal.\nfunction UIKit.Pop(object, startScale)\n\tlocal scale = UIKit.GetScale(object)\n\tscale.Scale = startScale or 1.2\n\tUIKit.Tween(scale, 0.45, { Scale = 1 }, Enum.EasingStyle.Back)\nend\n\n-- Label(parent, text, size, position, color, font): outlined text, positioned from its CENTER\nfunction UIKit.Label(parent, text, size, position, color, font)\n\tlocal label = UIKit.Create(\"TextLabel\", {\n\t\tText = text,\n\t\tSize = size,\n\t\tPosition = position,\n\t\tAnchorPoint = Vector2.new(0.5, 0.5), -- position = the center of the label\n\t\tBackgroundTransparency = 1,          -- just text, no box\n\t\tFont = font or Theme.TitleFont,\n\t\tTextColor3 = color or C.Text,\n\t\tTextScaled = true,                   -- text grows/shrinks to fit the label\n\t}, parent)\n\tUIKit.TextOutline(label)\n\treturn label\nend\n\n-- Panel(parent, size, position, color): a rounded box with an outline (cards, windows...)\nfunction UIKit.Panel(parent, size, position, color)\n\tcolor = color or C.Panel\n\tlocal panel = UIKit.Create(\"Frame\", {\n\t\tSize = size,\n\t\tPosition = position,\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\tBackgroundColor3 = Color3.new(1, 1, 1), -- white, so the gradient shows its true colors\n\t}, parent)\n\tUIKit.Corner(panel)\n\tUIKit.Outline(panel)\n\tUIKit.Gradient(panel, UIKit.Lighten(color, 0.08), color)\n\treturn panel\nend\n\n--[[\n\tButton(parent, text, color, size, position)\n\tA chunky 3D button: a darker \"base\" sits under the colored \"face\".\n\tPressing it pushes the face down onto the base, like a real button.\n\n\tGives back THREE things:\n\t  face   = the TextButton (connect .Activated to this)\n\t  holder = the invisible frame around it (move or hide THIS one)\n\t  label  = the text on it (change label.Text to change the words)\n]]\nfunction UIKit.Button(parent, text, color, size, position)\n\tlocal depth = Theme.ButtonDepth\n\n\tlocal holder = UIKit.Create(\"Frame\", {\n\t\tSize = size,\n\t\tPosition = position,\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\tBackgroundTransparency = 1,\n\t}, parent)\n\n\tlocal base = UIKit.Create(\"Frame\", { -- the dark part underneath\n\t\tSize = UDim2.new(1, 0, 1, -depth),\n\t\tPosition = UDim2.new(0, 0, 0, depth),\n\t\tBackgroundColor3 = UIKit.Darken(color, 0.45),\n\t}, holder)\n\tUIKit.Corner(base)\n\tUIKit.Outline(base)\n\n\tlocal face = UIKit.Create(\"TextButton\", { -- the colored top you click\n\t\tSize = UDim2.new(1, 0, 1, -depth),\n\t\tBackgroundColor3 = Color3.new(1, 1, 1),\n\t\tAutoButtonColor = false, -- turn off Roblox's default grey hover\n\t\tText = \"\", -- the words go in a separate label (below) so the shine can sit BEHIND them\n\t}, holder)\n\tUIKit.Corner(face)\n\tUIKit.Outline(face)\n\tUIKit.Gradient(face, UIKit.Lighten(color, 0.15), color)\n\n\tlocal shine = UIKit.Create(\"Frame\", { -- the glossy white strip at the top\n\t\tSize = UDim2.new(1, -10, 0.3, 0),\n\t\tPosition = UDim2.new(0, 5, 0, 4),\n\t\tBackgroundColor3 = Color3.new(1, 1, 1),\n\t\tBackgroundTransparency = 0.75,\n\t}, face)\n\tUIKit.Corner(shine, 8)\n\n\tlocal label = UIKit.Label(face, text, UDim2.new(0.85, 0, 0.62, 0), UDim2.new(0.5, 0, 0.5, 0))\n\tlabel.ZIndex = 2 -- higher ZIndex = drawn on top (so the text is above the shine)\n\n\t-- Animations\n\tlocal scale = UIKit.GetScale(holder)\n\tlocal up = UDim2.new(0, 0, 0, 0)\n\tlocal down = UDim2.new(0, 0, 0, depth)\n\n\tface.MouseEnter:Connect(function()\n\t\tUIKit.Tween(scale, 0.15, { Scale = 1.06 }, Enum.EasingStyle.Back) -- grow a little on hover\n\tend)\n\tface.MouseLeave:Connect(function()\n\t\tUIKit.Tween(scale, 0.15, { Scale = 1 }, Enum.EasingStyle.Back)\n\t\tUIKit.Tween(face, 0.08, { Position = up })\n\tend)\n\tface.MouseButton1Down:Connect(function()\n\t\tUIKit.Tween(face, 0.05, { Position = down }) -- push down onto the base\n\tend)\n\tface.MouseButton1Up:Connect(function()\n\t\tUIKit.Tween(face, 0.2, { Position = up }, Enum.EasingStyle.Back) -- spring back up\n\tend)\n\n\treturn face, holder, label\nend\n\n--[[\n\tBar(parent, size, position, color)\n\tA health/XP bar. Gives back a table: { Frame, Fill, Text }\n\tUse UIKit.SetBar(bar, 0.5, \"50 / 100\") to change it.\n]]\nfunction UIKit.Bar(parent, size, position, color)\n\tlocal back = UIKit.Create(\"Frame\", {\n\t\tSize = size,\n\t\tPosition = position,\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\tBackgroundColor3 = C.Slot,\n\t}, parent)\n\tUIKit.Corner(back, 10)\n\tUIKit.Outline(back)\n\n\tlocal fill = UIKit.Create(\"Frame\", {\n\t\tSize = UDim2.new(1, 0, 1, 0),\n\t\tBackgroundColor3 = Color3.new(1, 1, 1),\n\t}, back)\n\tUIKit.Corner(fill, 10)\n\tUIKit.Gradient(fill, UIKit.Lighten(color, 0.25), color)\n\n\tlocal text = UIKit.Label(back, \"\", UDim2.new(0.95, 0, 0.75, 0), UDim2.new(0.5, 0, 0.5, 0), C.Text, Theme.TextFont)\n\ttext.ZIndex = 2 -- draw it ON TOP of the fill\n\n\treturn { Frame = back, Fill = fill, Text = text }\nend\n\n-- SetBar(bar, percent, text): percent goes from 0 (empty) to 1 (full)\nfunction UIKit.SetBar(bar, percent, text)\n\tpercent = math.clamp(percent, 0, 1) -- clamp = keep it between 0 and 1\n\tUIKit.Tween(bar.Fill, 0.2, { Size = UDim2.new(percent, 0, 1, 0) })\n\tbar.Fill.Visible = percent > 0 -- a 0-wide bar with round corners looks glitchy, so hide it\n\tbar.Text.Text = text\nend\n\nreturn UIKit\n" i15.Parent=i10 i10.Parent=SP print("Anime game installed! Press PLAY.")